'use strict';
const canvas=document.querySelector('#game'),M=Meadow,flock=new Map(),keys={},pending={},flowers=[];let last=0,time=0,ui='',diag=0,keyboardEnabled=false,lastKey='none',lastKeyAt=0,hatNoticeUntil=0,fullscreenNoticeUntil=0;const hatNames=['No hat','Sunhat','Party hat','Flower crown'];const empty={x:0,y:0,jump:false,baa:false,bite:false,hat:false,wool:false};
const audio=MeadowAudio.create();const world=M.world();let bossAudio=false,eventText='';const debugEnabled=typeof location!=='undefined'&&['localhost','127.0.0.1','[::1]'].includes(location.hostname)&&new URLSearchParams(location.search).get('qa')==='1';
let view;
try{view=Meadow3D.create(canvas);}catch(error){view=MeadowFallback.create(canvas);document.querySelector('#toast').textContent='Reduced graphics mode · WebGL unavailable';}
function background(){view.world?.(world);view.begin();}function drawSheep(s,ghost=false){view.sheep(s,ghost);}
function join(id){if(flock.has(id))return flock.get(id);if(flock.size>=4)return null;const n=[0,1,2,3].find(n=>![...flock.values()].some(s=>s.n===n));const s=M.sheep(id,n);flock.set(id,s);document.querySelector('#welcome').hidden=true;return s;}
function eggCountdown(seconds){const ticks=Math.ceil(Math.max(0,seconds)*10);return Math.floor(ticks/600)+':'+((ticks%600)/10).toFixed(1).padStart(4,'0');}
function baa(s){audio.play(s.dragon?'roar':'baa');}
function scan(){try{return navigator.getGamepads?Array.from(navigator.getGamepads()).filter(p=>p&&p.connected):[];}catch(e){return[];}}
function keyboardInput(){let x=(keys.ArrowRight||keys.KeyD?1:0)-(keys.ArrowLeft||keys.KeyA?1:0),y=(keys.ArrowDown||keys.KeyS?1:0)-(keys.ArrowUp||keys.KeyW?1:0);let l=Math.hypot(x,y);return{x:l>1?x/l:x,y:l>1?y/l:y,jump:!!(keys.Space||pending.Space),baa:!!(keys.KeyX||pending.KeyX),bite:!!(keys.KeyB||pending.KeyB),hat:!!(keys.KeyH||pending.KeyH),wool:!!(keys.KeyC||pending.KeyC)};}
function frame(t){const elapsed=document.hidden||!last?0:Math.max(0,(t-last)/1000||0),dt=Math.min(elapsed,.05);last=t;time+=dt;const pads=scan();for(const p of pads){if(p.buttons[0]?.pressed)join('pad'+p.index);}M.stepWorld(world,[...flock.values()],elapsed);for(const s of flock.values()){const p=pads.find(p=>'pad'+p.index===s.id);s.connected=s.id==='keys'||!!p;let i=s.id==='keys'?keyboardInput():p?M.input(p):empty;if(s.id==='keys'){for(const [code,action]of [['Space','jump'],['KeyX','baa'],['KeyB','bite'],['KeyH','hat'],['KeyC','wool']])if(pending[code])s.prev[action]=false;}const old=s.baa,oldHat=s.hat,oldWool=s.woolIndex;M.step(s,i,elapsed);if(s.id==='keys')for(const code in pending)delete pending[code];if(s.baa>old)baa(s);if(s.attack)audio.play('chomp');if(s.fireAttack)audio.play('fire');if(s.woolIndex!==oldWool)woolNotice(s);if(s.hat!==oldHat){document.querySelector('#hatNotice').textContent='P'+(s.n+1)+': '+hatNames[s.hat];hatNoticeUntil=time+3;}}
const eggBefore=world.egg,eggHitsBefore=eggBefore?.hits??0;const aliveBefore=new Set([...flock.values()].filter(s=>s.ko<=0).map(s=>s.id));M.combat([...flock.values()],world);const eggHitsAdded=eggBefore?(world.egg===eggBefore?eggBefore.hits-eggHitsBefore:world.dragonOwner?M.rules.eggBites-eggHitsBefore:0):0;for(let n=0;n<eggHitsAdded;n++)audio.play('eggHit');for(const s of flock.values())if(aliveBefore.has(s.id)&&s.ko>0)audio.play('ko');for(const event of M.bounce?.([...flock.values()])||[])audio.play('bounce');const boss=!!world.dragonOwner;if(boss!==bossAudio){bossAudio=boss;if(boss){audio.play('eggBreak');audio.play('transform');}audio.setBoss?.(boss);document.body?.classList?.toggle('dragon-mode',boss);}const owner=flock.get(world.dragonOwner);const message=boss?'DRAGON! P'+((owner?.n??0)+1)+' · X roar · B '+(owner?.biteCool>0?'recharge '+owner.biteCool.toFixed(1)+'s':'FIRE READY')+' · '+world.dragonTime.toFixed(1)+'s':world.egg?'A dragon egg! Bite it 3 times · '+world.egg.hits+'/3 bites':'Dragon egg in '+eggCountdown(world.nextEggIn);if(message!==eventText){document.querySelector('#eventHud').textContent=message;eventText=message;}background();if(!flock.size){[[250,300],[430,500],[650,220],[850,410],[720,570],[360,220],[550,380],[920,590]].forEach(([x,y],n)=>{const s=M.sheep('demo',n);s.x=x;s.y=y;s.walk=time*.8;s.face=n%2?1:-1;s.heading=n%2?.4:-2.3;s.hat=n===3?1:0;drawSheep(s,true);});}else [...flock.values()].sort((a,b)=>a.y-b.y).forEach(s=>drawSheep(s));
view.render(time);if(fullscreenNoticeUntil&&time>fullscreenNoticeUntil){if(document.querySelector('#toast').textContent.startsWith('Expanded view'))document.querySelector('#toast').textContent='';fullscreenNoticeUntil=0;}document.querySelector('#hatNotice').hidden=time>hatNoticeUntil;const status=[...flock.values()].map(s=>`<span class="chip"><i style="background:${s.color}"></i>${s.id==='keys'?'Shared keyboard / touch':'P'+(s.n+1)+' · gamepad slot '+s.id.slice(3)}${s.connected?' · '+hatNames[s.hat]:' · reconnect controller'} <button data-wool="${s.id}" aria-label="Change P${s.n+1} wool color">Wool: ${s.woolIndex<0?'Cream':M.woolNames[s.woolIndex]}</button></span>`).join('');if(status!==ui){document.querySelector('#players').innerHTML=status;ui=status;}
if(t-diag>200){diag=t;const audioState=audio.status().label;const slotText=pads.map(p=>'slot '+p.index+' ['+(flock.has('pad'+p.index)?'joined':'press A')+']').join(' · ');document.querySelector('#inputHud').textContent='v12 dragon fire · Gamepads: '+pads.length+' · '+(slotText||'No separate controller slots yet')+' | Keys: '+(keyboardEnabled?'shared fallback ON':'fallback OFF')+' ('+lastKey+')'+' | Audio: '+audioState;document.querySelector('#padStatus').textContent=(navigator.getGamepads?'Gamepad API available':'Gamepad API unavailable')+'\nSeparate controller slots: '+pads.length+' / Sheep joined: '+flock.size+'\nLast keyboard event: '+lastKey+(lastKeyAt?' ('+Math.round((performance.now()-lastKeyAt)/1000)+'s ago)':'')+'\nKeyboard events have no controller identity. Fallback is '+(keyboardEnabled?'ON (one shared sheep)':'OFF')+'.\nAudio engine: '+audioState+'\n'+pads.map(p=>'SLOT '+p.index+': '+p.id+'\n mapping: '+(p.mapping||'nonstandard')+' | axes: '+p.axes.map(x=>x.toFixed(2)).join(', ')+' | held buttons: '+(p.buttons.map((b,i)=>b.pressed?i:null).filter(x=>x!==null).join(', ')||'none')).join('\n');updateSoundLabel();}requestAnimationFrame(frame);}
function updateSoundLabel(){document.querySelector('#inputMode').textContent=keyboardEnabled?'Keyboard: WASD / arrows · Space hop · X baa · B chomp · H hat · C wool':'Controller: stick / D-pad · A hop · X baa · B chomp · Y hat · RB wool';const state=audio.status();document.querySelector('#sound').textContent=state.effectsEnabled?'Sounds on':'Sounds off';document.querySelector('#sound').setAttribute('aria-pressed',String(state.effectsEnabled));document.querySelector('#music').textContent=state.musicEnabled?'Music on':'Music off';document.querySelector('#music').setAttribute('aria-pressed',String(state.musicEnabled));document.querySelector('#audioStart').hidden=state.state==='running';document.querySelector('#audioStatus').textContent='Audio: '+state.label+' · Music '+(state.musicPlaying?'playing':state.musicEnabled?'enabled':'off')+' · Sound effects '+(state.effectsEnabled?'enabled':'off');}
function enableSound(test=false){audio.activate().then(()=>audio.preload()).then(()=>{if(test)audio.play('baa');updateSoundLabel();});}
document.querySelector('#start').onclick=()=>{enableSound();document.querySelector('#welcome').hidden=true;canvas.focus();};
document.querySelector('#keyboard').onclick=()=>{keyboardEnabled=!keyboardEnabled;clear();if(keyboardEnabled){const s=join('keys');if(!s){keyboardEnabled=false;document.querySelector('#toast').textContent='All four sheep slots are occupied.';}else enableSound();}else flock.delete('keys');document.querySelector('#keyboard').textContent=keyboardEnabled?'Turn off shared keys':'Keyboard / touch';canvas.focus();};document.querySelector('#sound').onclick=()=>{audio.setEffects(!audio.status().effectsEnabled);enableSound(false);updateSoundLabel();};document.querySelector('#music').onclick=()=>{audio.setMusic(!audio.status().musicEnabled);enableSound(false);updateSoundLabel();};document.querySelector('#audioStart').onclick=()=>enableSound(true);document.querySelector('#testBaa').onclick=()=>enableSound(true);document.querySelector('#testChomp').onclick=()=>{audio.activate().then(()=>audio.preload()).then(()=>audio.play('chomp'));};
function immersive(on){if(!on&&document.querySelector('#toast').textContent.startsWith('Expanded view'))document.querySelector('#toast').textContent='';document.body.classList.toggle('immersive',on);document.querySelector('#fullscreen').textContent=on?'Exit full view ↙':'Full screen ↗';}document.querySelector('#fullscreen').onclick=async()=>{const on=!document.body.classList.contains('immersive');immersive(on);try{if(!on&&document.fullscreenElement)await document.exitFullscreen();else if(on&&!document.fullscreenElement)await document.documentElement.requestFullscreen();}catch(e){document.querySelector('#toast').textContent='Expanded view on · use your browser’s fullscreen option to hide browser controls.';fullscreenNoticeUntil=time+6;}};document.addEventListener('fullscreenchange',()=>immersive(!!document.fullscreenElement));document.querySelector('#help').onclick=()=>{const d=document.querySelector('#diagnostics');d.open=!d.open;};
const allowed=['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD','Space','KeyX','KeyB','KeyH','KeyC'];addEventListener('keydown',e=>{if(!allowed.includes(e.code)||/INPUT|TEXTAREA/.test(e.target.tagName))return;if(e.target.tagName==='BUTTON'&&(e.code==='Space'))return;lastKey=e.code;lastKeyAt=performance.now();if(!keyboardEnabled)return;e.preventDefault();keys[e.code]=true;if(!e.repeat&&['Space','KeyX','KeyB','KeyH','KeyC'].includes(e.code))pending[e.code]=true;if(audio.status().state!=='running')enableSound(false);});addEventListener('keyup',e=>{keys[e.code]=false;});function clear(){for(const k in keys)keys[k]=false;for(const k in pending)delete pending[k];}addEventListener('blur',clear);document.addEventListener('visibilitychange',()=>{clear();last=performance.now();audio.visibility(document.hidden);});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();keyboardEnabled=true;join('keys');enableSound(false);keys[b.dataset.key]=true;if(['Space','KeyX','KeyB','KeyH','KeyC'].includes(b.dataset.key))pending[b.dataset.key]=true;b.setPointerCapture(e.pointerId);};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys[b.dataset.key]=false);});requestAnimationFrame(frame);

function woolNotice(s){document.querySelector('#hatNotice').textContent='P'+(s.n+1)+': '+M.woolNames[s.woolIndex]+' wool';hatNoticeUntil=time+3;}
document.querySelector('#players').onclick=e=>{const button=e.target.closest('[data-wool]');if(!button)return;const s=flock.get(button.dataset.wool);if(s){M.cycleWool(s);woolNotice(s);}canvas.focus();};

if(debugEnabled){const panel=document.querySelector('#qaTools');panel.hidden=false;document.querySelector('#qaAdvance').onclick=()=>{M.stepWorld(world,[...flock.values()],30);for(const s of flock.values())M.step(s,empty,30);};document.querySelector('#qaEgg').onclick=()=>{if(!flock.size)join('keys');world.nextEggIn=0;M.stepWorld(world,[...flock.values()],.001);const p=[...flock.values()][0];if(world.egg){world.egg.x=p.x+Math.cos(p.heading)*50;world.egg.y=p.y+Math.sin(p.heading)*50;world.egg.z=0;world.egg.vx=0;world.egg.vy=0;}};document.querySelector('#qaSheep').onclick=()=>{const s=join('qa');const p=[...flock.values()][0];if(s&&s!==p){s.x=p.x+120;s.y=p.y;}};}
